/** Physical input checks for desktop placement, taskbar toggling and Documents navigation. */
public class ContinuitySmoke extends Instrumentation {
    private MainActivity home;private View root;private DesktopStore store;private File musicProbe;private final Map<String,Object> originalSettings=new HashMap<>();
    private final BlockingQueue<MainActivity> resumed=new LinkedBlockingQueue<>();
    private final Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityResumed(Activity a){if(a instanceof MainActivity)resumed.offer((MainActivity)a);}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle result=new Bundle();Application app=(Application)getTargetContext().getApplicationContext();app.registerActivityLifecycleCallbacks(lifecycle);try{
        store=new DesktopStore(getTargetContext());for(String key:Arrays.asList("shortcuts","desktop_positions_portrait","desktop_positions_landscape","snap_desktop","layout_locked","reduce_motion","show_status_bar"))originalSettings.put(key,store.prefs.getAll().get(key));store.desktop(Arrays.asList("@computer","@browser","@notes","@appearance"));store.prefs.edit().putBoolean("snap_desktop",true).putBoolean("layout_locked",false).putBoolean("reduce_motion",true).remove("desktop_positions_portrait").remove("desktop_positions_landscape").commit();home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();await(()->find(v->v instanceof DesktopIconGrid)!=null,"Desktop ready");Thread.sleep(300);
        progress("real taskbar taps toggle the active window and raise a covered window");ui(()->home.open("@computer"));DesktopWindow computer=window("@computer");task("Minimize Computer");await(()->computer.getVisibility()==View.GONE,"Taskbar minimizes active folder");task("Restore Computer");await(()->computer.isShown()&&computer.active(),"Taskbar restores the same folder");ui(()->home.open("@notes"));DesktopWindow notes=window("@notes");task("Restore Computer");await(()->computer.active()&&notes.isShown(),"Covered folder comes to front without hiding other tools");task("Minimize Computer");await(()->!computer.isShown(),"Second tap minimizes foreground folder");ui(()->{notes.setVisibility(View.GONE);});
        progress("Start Documents and Computer Documents open the primary Documents directory");java.io.File documents=Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOCUMENTS);check(documents.isDirectory()||documents.mkdirs(),"Documents directory exists");String name="Nth-Documents-"+SystemClock.uptimeMillis()+".txt";java.io.File probe=new java.io.File(documents,name);try(java.io.FileOutputStream out=new java.io.FileOutputStream(probe)){out.write("Documents path check".getBytes(java.nio.charset.StandardCharsets.UTF_8));}
        tap(find(v->"Start menu".equals(v.getContentDescription())));await(()->find(v->v instanceof StartMenu)!=null,"Start opened");View start=find(v->v instanceof StartMenu);tap(find(start,v->v instanceof TextView&&"Documents".contentEquals(((TextView)v).getText())));await(()->find(v->name.equals(v.getContentDescription()))!=null,"Start Documents contains file from physical Documents");DesktopWindow documentWindow=window("@documents");
        check(documentWindow!=null&&documentWindow!=computer,"Start gives Documents an independent Explorer window");
        VistaExplorer explorer=(VistaExplorer)documentWindow.body;
        check("primary:Documents".equals(DocumentsContract.getDocumentId(DocumentOps.current(explorer.page()))),"Start opens primary Documents");
        await(()->find(v->"Folder windows, 2 windows".equals(v.getContentDescription()))!=null,"Computer and Documents share one Explorer taskbar button");
        ui(()->home.open("@computer"));View documentsRow=find(computer,v->"Documents".equals(v.getContentDescription()));tap(documentsRow);await(()->find(computer,v->name.equals(v.getContentDescription()))!=null,"Computer Documents reaches same real folder");probe.delete();
        ui(()->{for(int i=0;i<((ViewGroup)computer.getParent()).getChildCount();i++){View v=((ViewGroup)computer.getParent()).getChildAt(i);if(v instanceof DesktopWindow)v.setVisibility(View.GONE);}});
        progress("actual shortcut drag to blank space, setting checkbox and durable free positions");DesktopIconGrid grid=(DesktopIconGrid)find(v->v instanceof DesktopIconGrid);View icon=find(grid,v->"@computer".equals(v.getTag()));View neighbor=find(grid,v->"@browser".equals(v.getTag()));float neighborX=neighbor.getLeft(),neighborY=neighbor.getTop();int[] location=new int[2];grid.getLocationOnScreen(location);float density=home.getResources().getDisplayMetrics().density;drag(icon,location[0]+Math.min(grid.getWidth()-20*density,135*density),location[1]+355*density);await(()->store.prefs.getString("desktop_positions_portrait","{}").contains("@computer"),"Blank desktop accepts shortcut drop");check(icon.getTop()>200*density,"Dropped shortcut actually moved into empty space");await(()->{View other=find(v->"@browser".equals(v.getTag()));return other!=null&&other.getLeft()==neighborX&&other.getTop()==neighborY;},"Moving one shortcut keeps neighboring shortcuts in place");shot("desktop-snapped");ui(()->{home.open("@control");((VistaControlPanel)window("@control").body).navigate("icons");});getUiAutomation().waitForIdle(300,3000);CheckBox snap=(CheckBox)find(v->"Snap desktop apps to grid".equals(v.getContentDescription()));check(snap!=null&&snap.isChecked(),"Snap checkbox lives on Desktop Settings page");tap(snap);await(()->!store.prefs.getBoolean("snap_desktop",true),"Checkbox disables snapping");ui(()->window("@control").setVisibility(View.GONE));grid=(DesktopIconGrid)find(v->v instanceof DesktopIconGrid);icon=find(grid,v->"@computer".equals(v.getTag()));grid.getLocationOnScreen(location);float x=Math.min(grid.getWidth()-45*density,117*density),y=450*density;drag(icon,location[0]+x,location[1]+y);final View moved=icon;check(Math.abs(moved.getTop()/density/store.tileHeight()-Math.round(moved.getTop()/density/store.tileHeight()))>.08,"Free drop keeps a position between grid rows; actual top="+moved.getTop()/density);String positions=store.prefs.getString("desktop_positions_portrait","{}");float top=icon.getTop();shot("desktop-free");MainActivity before=home;resumed.clear();ui(home::recreate);long end=SystemClock.uptimeMillis()+12000;MainActivity next=null;while(SystemClock.uptimeMillis()<end){MainActivity candidate=resumed.poll(100,TimeUnit.MILLISECONDS);if(candidate!=null&&candidate!=before){next=candidate;break;}}check(next!=null,"Explicit recreation finished");home=next;root=home.getWindow().getDecorView();await(()->find(v->"@computer".equals(v.getTag()))!=null,"Desktop restored");await(()->{View restored=find(v->"@computer".equals(v.getTag()));return restored!=null&&Math.abs(restored.getTop()-top)<2;},"Free position survives Activity recreation after desktop rendering settles");ui(()->home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));await(()->root.getWidth()>root.getHeight(),"Landscape settles");ui(()->home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));await(()->root.getHeight()>root.getWidth(),"Portrait settles");check(positions.equals(store.prefs.getString("desktop_positions_portrait","{}")),"Landscape preserves separate portrait positions");DesktopBackup.Plan backup=DesktopBackup.parse(DesktopBackup.snapshot(store).toString());check(backup.string("desktop_positions_portrait","{}").contains("@computer")&&Boolean.FALSE.equals(backup.values.get("snap_desktop")),"Validated backup includes positions and snap preference");
        polishChecks();
        result.putString("stream","PASS: Vista System displays installed package and hardware information; Start orb touch menu routes Properties; held/mouse-hovered Start links paint Aero selection; Music opens native Nth Explorer;  physical taskbar taps minimize/restore/raise existing folder windows; Start and Computer Documents reach primary shared Documents and its actual files; physical shortcut drags to blank desktop work with snap on/off; requested settings checkbox updates snapping; free positions survive Activity recreation and both orientations; desktop positions and snap setting survive validated backups.\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable failure){try{shot("continuity-failure");}catch(Exception ignored){}StringWriter text=new StringWriter();failure.printStackTrace(new PrintWriter(text));result.putString("stream","FAIL: "+text);finish(Activity.RESULT_CANCELED,result);}finally{if(musicProbe!=null)musicProbe.delete();if(store!=null){android.content.SharedPreferences.Editor edit=store.prefs.edit();for(Map.Entry<String,Object> entry:originalSettings.entrySet()){Object value=entry.getValue();if(value==null)edit.remove(entry.getKey());else if(value instanceof String)edit.putString(entry.getKey(),(String)value);else if(value instanceof Boolean)edit.putBoolean(entry.getKey(),(Boolean)value);}edit.commit();}app.unregisterActivityLifecycleCallbacks(lifecycle);}}
    private void polishChecks()throws Exception{
        progress("Vista System uses the actual installed build and device information");ui(()->home.open("@system"));await(()->find(v->"Installed Nth Desktop version".equals(v.getContentDescription()))!=null,"System information opens");TextView version=(TextView)find(v->"Installed Nth Desktop version".equals(v.getContentDescription()));check(version.getText().toString().contains(AppInfo.version(getTargetContext()))&&version.getText().toString().contains(Long.toString(AppInfo.build(getTargetContext()))),"System shows installed version and build");check(find(v->"system:Manufacturer".equals(v.getTag())&&v instanceof TextView&&Build.MANUFACTURER.contentEquals(((TextView)v).getText()))!=null,"System shows the real manufacturer");check(find(v->"system:Model".equals(v.getTag())&&v instanceof TextView&&Build.MODEL.contentEquals(((TextView)v).getText()))!=null,"System shows the real device model");check(find(window("@system"),v->v instanceof TextView&&((TextView)v).getText().toString().contains("0.11.0"))==null,"Old hard-coded System version is gone");shot("vista-system");ui(()->{window("@system").setVisibility(View.GONE);DesktopWindow control=window("@control");if(control!=null)control.setVisibility(View.GONE);});
        progress("actual Start orb context menu and Properties destination");hold(find(v->"Start menu".equals(v.getContentDescription())));awaitMenu("Explore");awaitMenu("Properties");shot("start-orb-menu");menuTap("Properties");await(()->window("@control")!=null&&((VistaControlPanel)window("@control").body).page().equals("taskbar")&&find(window("@control"),v->"Show Android app taskbar buttons".equals(v.getContentDescription()))!=null,"Start Properties opens Taskbar and Start Menu settings");ui(()->window("@control").setVisibility(View.GONE));
        progress("held Start options and mouse hover paint Aero without launching; Music stays in Nth Explorer");tap(find(v->"Start menu".equals(v.getContentDescription())));StartMenu menu=(StartMenu)find(v->v instanceof StartMenu);check(menu!=null,"Start menu is open");View music=find(menu,v->"Music".equals(v.getContentDescription()));int before=sample(music);hold(music);await(()->music.isSelected()&&menu.isShown(),"Holding a Start link highlights it without opening it");int after=sample(music);check(Color.alpha(after)>Color.alpha(before)+40,"Held link paints a visible Aero surface");shot("start-hover");View documents=find(menu,v->"Documents".equals(v.getContentDescription()));hover(documents);await(()->documents.isHovered()&&!music.isSelected(),"Mouse hover transfers the Start highlight");
        File folder=Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_MUSIC);check(folder.isDirectory()||folder.mkdirs(),"Music directory exists");musicProbe=new File(folder,"Nth-Music-"+SystemClock.uptimeMillis()+".txt");try(FileOutputStream out=new FileOutputStream(musicProbe)){out.write("native music directory".getBytes(java.nio.charset.StandardCharsets.UTF_8));}tap(music);await(()->find(v->musicProbe.getName().equals(v.getContentDescription()))!=null,"Start Music opens the real native Music directory");VistaExplorer explorer=(VistaExplorer)window("@music").body;check("primary:Music".equals(DocumentsContract.getDocumentId(DocumentOps.current(explorer.page()))),"Music uses Nth Explorer and the device Music path");shot("start-music");musicProbe.delete();musicProbe=null;
        ui(()->home.open("@browser"));await(()->window("@browser")!=null,"Renamed browser opens");check(find(window("@browser"),v->v instanceof TextView&&BrowserPanel.NAME.contentEquals(((TextView)v).getText()))!=null,"Browser window carries its new name");check(StartSearch.find(store,Collections.emptyList(),"Nth Internet Explorer").stream().anyMatch(r->r.id.equals("@browser")&&r.title.equals(BrowserPanel.NAME)),"Browser is discoverable by its new name");
    }
    private int sample(View view){int[] value={0};runOnMainSync(()->{Bitmap bitmap=Bitmap.createBitmap(view.getWidth(),view.getHeight(),Bitmap.Config.ARGB_8888);view.draw(new Canvas(bitmap));value[0]=bitmap.getPixel(Math.min(bitmap.getWidth()-1,Aero.dp(home,3)),bitmap.getHeight()/2);bitmap.recycle();});return value[0];}
    private void hold(View view)throws Exception{Rect rect=new Rect();check(view!=null&&view.getGlobalVisibleRect(rect),"Hold target has visible bounds");long down=SystemClock.uptimeMillis();input(down,MotionEvent.ACTION_DOWN,rect.exactCenterX(),rect.exactCenterY());Thread.sleep(700);input(down,MotionEvent.ACTION_UP,rect.exactCenterX(),rect.exactCenterY());Thread.sleep(180);}
    private void hover(View view)throws Exception{Rect rect=new Rect();check(view!=null&&view.getGlobalVisibleRect(rect),"Hover target has visible bounds");MotionEvent.PointerProperties properties=new MotionEvent.PointerProperties();properties.id=0;properties.toolType=MotionEvent.TOOL_TYPE_MOUSE;MotionEvent.PointerCoords point=new MotionEvent.PointerCoords();point.x=rect.exactCenterX();point.y=rect.exactCenterY();long now=SystemClock.uptimeMillis();MotionEvent event=MotionEvent.obtain(now,now,MotionEvent.ACTION_HOVER_MOVE,1,new MotionEvent.PointerProperties[]{properties},new MotionEvent.PointerCoords[]{point},0,0,1,1,0,0,InputDevice.SOURCE_MOUSE,0);check(getUiAutomation().injectInputEvent(event,true),"Mouse hover injected");event.recycle();Thread.sleep(180);}
    private android.view.accessibility.AccessibilityNodeInfo menuNode(String text){return menuNode(getUiAutomation().getRootInActiveWindow(),text);}
    private android.view.accessibility.AccessibilityNodeInfo menuNode(android.view.accessibility.AccessibilityNodeInfo node,String text){if(node==null)return null;if(text.contentEquals(node.getText()==null?"":node.getText())||text.contentEquals(node.getContentDescription()==null?"":node.getContentDescription()))return node;for(int i=0;i<node.getChildCount();i++){android.view.accessibility.AccessibilityNodeInfo found=menuNode(node.getChild(i),text);if(found!=null)return found;}return null;}
    private void awaitMenu(String text)throws Exception{long end=SystemClock.uptimeMillis()+8000;while(SystemClock.uptimeMillis()<end){if(menuNode(text)!=null)return;Thread.sleep(100);}throw new AssertionError("Start menu item is available: "+text);}
    private void menuTap(String text)throws Exception{awaitMenu(text);android.view.accessibility.AccessibilityNodeInfo node=menuNode(text);Rect rect=new Rect();node.getBoundsInScreen(rect);long now=SystemClock.uptimeMillis();input(now,MotionEvent.ACTION_DOWN,rect.exactCenterX(),rect.exactCenterY());input(now,MotionEvent.ACTION_UP,rect.exactCenterX(),rect.exactCenterY());Thread.sleep(250);}
    private DesktopWindow window(String id){return (DesktopWindow)find(v->v instanceof DesktopWindow&&id.equals(((DesktopWindow)v).toolId));}
    private void task(String label)throws Exception{View button=find(v->label.equals(v.getContentDescription()));check(button!=null,"Taskbar action exists: "+label);View ancestor=button;while(ancestor.getParent() instanceof View&&!(ancestor instanceof HorizontalScrollView))ancestor=(View)ancestor.getParent();check(ancestor instanceof HorizontalScrollView,"Taskbar scroll exists");HorizontalScrollView scroll=(HorizontalScrollView)ancestor;ui(()->{scroll.setSmoothScrollingEnabled(false);scroll.fullScroll(View.FOCUS_RIGHT);});getUiAutomation().waitForIdle(250,3000);View target=find(v->label.equals(v.getContentDescription()));Rect visible=new Rect();if(target==null||!target.getGlobalVisibleRect(visible))progress("Taskbar diagnostics: "+label+", strip="+scroll.getWidth()+"x"+scroll.getHeight()+", scroll="+scroll.getScrollX()+", child="+scroll.getChildAt(0).getWidth()+"x"+scroll.getChildAt(0).getHeight()+", target="+(target==null?"null":target.getWidth()+"x"+target.getHeight()+" @ "+target.getLeft()));tap(target);}
    private void drag(View view,float x,float y)throws Exception{Rect bounds=new Rect();check(view!=null&&view.getGlobalVisibleRect(bounds),"Shortcut has visible drag bounds");float sx=bounds.exactCenterX(),sy=bounds.exactCenterY();long down=SystemClock.uptimeMillis();input(down,MotionEvent.ACTION_DOWN,sx,sy);Thread.sleep(700);for(int i=1;i<=14;i++){input(down,MotionEvent.ACTION_MOVE,sx+(x-sx)*i/14,sy+(y-sy)*i/14);Thread.sleep(25);}input(down,MotionEvent.ACTION_UP,x,y);Thread.sleep(250);waitForIdleSync();}
    private void tap(View view)throws Exception{
        getUiAutomation().waitForIdle(250,3000);String description=view==null||view.getContentDescription()==null?null:view.getContentDescription().toString();
        if(description!=null){View current=find(v->description.equals(v.getContentDescription()));if(current!=null)view=current;}
        check(view!=null&&view.isAttachedToWindow(),"Touch target belongs to the current Activity");View target=view;ui(()->target.requestRectangleOnScreen(new Rect(0,0,target.getWidth(),target.getHeight()),true));getUiAutomation().waitForIdle(250,3000);
        if(description!=null){View current=find(v->description.equals(v.getContentDescription()));if(current!=null)view=current;}
        Rect rect=new Rect();check(view!=null&&view.isAttachedToWindow()&&view.isEnabled()&&view.getGlobalVisibleRect(rect),"Control has visible touch bounds");long down=SystemClock.uptimeMillis();input(down,MotionEvent.ACTION_DOWN,rect.exactCenterX(),rect.exactCenterY());Thread.sleep(65);input(down,MotionEvent.ACTION_UP,rect.exactCenterX(),rect.exactCenterY());Thread.sleep(200);
    }

    private void input(long down,int action,float x,float y){MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,y,0);e.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(getUiAutomation().injectInputEvent(e,true),"Touch accepted");e.recycle();}
    private View find(Predicate<View> test){return find(root,test);}private View find(View view,Predicate<View> test){if(view==null||!view.isShown())return null;if(test.test(view))return view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){View found=find(((ViewGroup)view).getChildAt(i),test);if(found!=null)return found;}return null;}
    private void await(BooleanSupplier test,String message)throws Exception{long end=SystemClock.uptimeMillis()+12000;while(SystemClock.uptimeMillis()<end){boolean[] ok={false};runOnMainSync(()->ok[0]=test.getAsBoolean());if(ok[0])return;Thread.sleep(80);}throw new AssertionError(message);}
    private void ui(Runnable task){runOnMainSync(task);try{Thread.sleep(150);}catch(InterruptedException ex){throw new AssertionError(ex);}}
    private void shot(String name)throws Exception{Bitmap image=getUiAutomation().takeScreenshot();check(image!=null,"Screenshot exists");try(FileOutputStream out=getTargetContext().openFileOutput(name+".png",0)){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
    private void check(boolean value,String message){if(!value)throw new AssertionError(message);}private void progress(String message){Bundle b=new Bundle();b.putString("stream","CHECK: "+message+"\n");sendStatus(1,b);}
}
